"""Original Russian glossary for the independent Jenkins engineering volume.

Pure educational data. No installation, network requests or commands on import.
"""

GLOSSARY = [
    ('JENKINS_HOME', 'Корневой каталог состояния конкретного экземпляра Jenkins: конфигурация, пользователи, задания, история, плагины и ключевые материалы. Повторный запуск с другим каталогом создаёт другую среду, даже если WAR и HTTP-порт совпадают.'),
    ('WAR Jenkins', 'Web application archive — архив веб-приложения. Самостоятельная поставка Jenkins включает серверную оболочку и запускается подходящей JVM, но не устанавливает автоматически инструменты Go-проекта и весь набор плагинов Pipeline.'),
    ('Winstone', 'Оболочка серверного контейнера в самостоятельной WAR-поставке Jenkins. Разбирает применимые параметры запуска веб-сервера и участвует в предоставлении HTTP-интерфейса; её параметры следует отличать от параметров самой JVM.'),
    ('Jetty', 'Java-компонент серверного контейнера, используемый самостоятельной поставкой Jenkins для обслуживания веб-запросов. Принимающий HTTP-процесс и агентские процессы сборки выполняют разные роли и требуют отдельных ресурсов.'),
    ('Java heap', 'Управляемая куча JVM, в которой размещаются Java-объекты. Предел Xmx относится к этой области, а RSS процесса дополнительно включает стеки, метаданные классов, код и другие нативные расходы.'),
    ('Metaspace', 'Область памяти HotSpot JVM для метаданных загруженных классов. Рост числа компонентов и загрузчиков способен увеличивать её отдельно от Java-кучи, поэтому одного значения занятого heap недостаточно для полного учёта памяти контроллера.'),
    ('Xmx', 'Параметр JVM максимального размера управляемой кучи, например -Xmx512m. Он ограничивает одну область памяти Java-процесса; процессы компиляции, агент, ОС и прочие области памяти учитываются дополнительно.'),
    ('Jenkins URL', 'Настроенный основной адрес контроллера, используемый при формировании ссылок и сведений интеграций. Он должен соответствовать реальному внешнему пути; изменение порта слушателя не переписывает его автоматически.'),
    ('Префикс Jenkins', 'Часть HTTP-пути, под которой размещён экземпляр, например /jenkins. Прокси и сервер должны согласованно обрабатывать её для страниц, перенаправлений, ресурсов и подключений агентов.'),
    ('LTS Jenkins', 'Ветка Jenkins с длительным сопровождением и отдельными исправляющими выпусками. Выбор LTS помогает планировать обновления, но не заменяет проверку Java, плагинов и сохранённых данных при переходе.'),
    ('Update Center', 'Источник метаданных об актуальных расширениях Jenkins, их версиях и зависимостях. Доступность списка и доступность бинарных архивов проверяются отдельно; автономный запуск требует заранее полученных файлов.'),
    ('Plugin ID', 'Точный идентификатор расширения Jenkins, например workflow-cps. В отличие от человекочитаемого заголовка он используется в списках установки, зависимостях и фиксации состава.'),
    ('requiredCore', 'Требование плагина к минимальному Jenkins, с которым он может работать. Наличие JPI на диске при слишком старом ядре не означает успешной загрузки или совместимого исполнения.'),
    ('Зависимость плагина', 'Требование расширения к другому компоненту и его версии. Обязательные зависимости должны образовывать полный совместимый набор; отказ одного узла может сделать недоступными несколько использующих его функций.'),
    ('Plugin lock', 'Зафиксированный перечень идентификаторов и версий полного проверенного набора расширений. Обычный список нескольких желаемых плагинов без транзитивных зависимостей ещё не определяет весь исполняемый состав контроллера.'),
    ('Plugin Installation Manager', 'Отдельная программа подготовки архивов плагинов с учётом целевого Jenkins и зависимостей. Она помогает получить автономный набор, но успешная загрузка файлов не заменяет проверку фактически активного состава на сервере.'),
    ('JPI и HPI', 'Применяемые расширения имён архивов плагинов Jenkins. Суффикс сам по себе не устанавливает доверие: проверяют происхождение, версию, совместимость и соответствие утверждённым байтам.'),
    ('Security realm', 'Механизм Jenkins, определяющий источник учётных записей и установление личности пользователя. Он отвечает за аутентификацию, а перечень разрешённых действий задаётся стратегией авторизации.'),
    ('Authorization strategy', 'Правила определения того, какие действия разрешены установленной личности над конкретными объектами Jenkins. Их проверяют отдельно от входа: успешный пароль не означает административные права.'),
    ('RBAC Jenkins', 'Role-based access control — назначение прав через роли и области объектов. Конкретная реализация зависит от выбранной стратегии и плагинов; имя роли без списка полномочий ничего не гарантирует.'),
    ('Crumb', 'Защитный маркер Jenkins для применимых изменяющих HTTP-запросов, связанный с контекстом пользователя и сессии. Он помогает противодействовать CSRF и не является паролем пользователя или секретом агента.'),
    ('CSRF Jenkins', 'Подделка запроса, при которой чужая страница пытается использовать браузерную сессию вошедшего пользователя для действия в Jenkins. Защитный crumb и корректный способ API-аутентификации относятся к этой границе, отдельно от обычных прав.'),
    ('Script Approval', 'Процедура административного одобрения управляющего скрипта или чувствительного вызова. Решение расширяет доверие к коду и его автору, поэтому его принимают по смыслу доступа, а не только ради исчезновения ошибки.'),
    ('Groovy sandbox', 'Проверка допустимости вызовов управляющего Groovy-кода Pipeline. Она не изолирует произвольную команду sh от файлов и сети агентской ОС; для этого нужны отдельные права и среда выполнения.'),
    ('Trusted Shared Library', 'Доверенная общая библиотека Jenkins, способная выполнять управляющую логику с расширенными полномочиями. Право менять её исходники может влиять на множество заданий и требует соответствующей защиты репозитория и выбора версии.'),
    ('Inbound agent', 'Агент, который сам инициирует подключение к контроллеру под зарегистрированным именем. После установления канала контроллер посылает работу; термин описывает инициативу соединения, а не отдельную виртуальную машину.'),
    ('WebSocket agent', 'Inbound-агент, использующий транспорт WebSocket через HTTP(S)-соединение. Отдельный TCP-порт агентов не нужен, но аутентификация, совместимость Remoting и корректная работа прокси остаются необходимыми.'),
    ('SSH launcher', 'Способ запуска агентского процесса, при котором контроллер соединяется с машиной по SSH и начинает Remoting. Проверка ключа машины, права пользователя и доступность Java являются отдельными этапами запуска.'),
    ('Секрет агента', 'Материал аутентификации inbound-подключения под определённым именем узла. Его хранят с ограниченным доступом; пароль браузерного пользователя и этот секрет имеют разное назначение.'),
    ('Remoting workDir', 'Внутренний каталог библиотеки Remoting для журналов, кэша JAR и связанных метаданных. Он отличается от текущего рабочего каталога каждой сборочной команды и от дома контроллера.'),
    ('JAR cache агента', 'Кэш требуемых Java-классов и архивов на стороне Remoting. Его наличие ускоряет взаимодействие, но не означает установки Go, Python, зависимостей приложения или сохранения выпускных артефактов.'),
    ('Канал Remoting', 'Логическое соединение контроллера и агентской JVM для управляющих вызовов, данных и результатов. Потеря канала не доказывает немедленного завершения всех дочерних процессов и не отменяет уже выполненное внешнее действие.'),
    ('CPS Pipeline', 'Continuation-passing style — преобразование управляющей программы в форму, пригодную для приостановки и сохранения продолжения. Этот механизм помогает возобновлению после предусмотренных перезапусков и накладывает ограничения на сохраняемые объекты и вызовы.'),
    ('Продолжение Pipeline', 'Сохраняемое представление того, какие значения нужны и какой управляющий код должен исполняться после ожидаемого шага. Оно не является снимком всей памяти агента и внешних служб.'),
    ('program.dat', 'Файл, связанный с сериализованным состоянием CPS-программы конкретного запуска. Его наличие рассматривают вместе с графом, данными шагов и агентским состоянием; прямое редактирование не является интерфейсом управления.'),
    ('FlowNode', 'Узел графа исполнения Pipeline, отражающий событие или шаг и его связи с другими узлами. По графу строятся наблюдаемые стадии и ветвления; это отличается от дерева коммитов Git и от процессов ОС.'),
    ('Durability Pipeline', 'Режим частоты и способа сохранения управляющего состояния Jenkins Pipeline. Более производительная настройка может изменить восстановление при аварии; она не задаёт надёжность внешней базы или самой операции доставки.'),
    ('@NonCPS', 'Аннотация метода Groovy, исключающая его из CPS-преобразования. Метод остаётся на контроллере и не предназначен для асинхронных шагов sh или sleep; возвращаемые управляющие данные должны быть пригодны для дальнейшего сохранения.'),
    ('Сериализация Pipeline', 'Преобразование достижимого управляющего состояния в сохраняемое представление. Неподходящий объект, удерживаемый между шагами, может вызвать NotSerializableException; сокращение частоты записи не исправляет его логическую непригодность.'),
    ('Контрольная точка Pipeline', 'Граница, относительно которой сохраняется пригодное для продолжения состояние управления. Она не является общей транзакцией с внешней системой и не обещает отмену либо однократность произвольного побочного действия.'),
    ('Matrix Pipeline', 'Декларативное описание комбинаций осей проверки, например версий инструмента и ОС. Каждая ячейка требует подходящих ресурсов и изоляции данных; переменная с именем версии не устанавливает инструмент.'),
    ('Parallel Pipeline', 'Одновременное продвижение нескольких ветвей управляющего графа. Фактическое выполнение команд зависит от доступных агентов, слотов и общих ресурсов, а безопасность требует независимости файлов, портов и данных.'),
    ('Fail-fast Pipeline', 'Политика прекращения остальных параллельных ветвей при отказе одной. Она сокращает лишнее ожидание, но меняет полноту собранных отчётов и не отменяет уже выполненные внешние действия.'),
    ('timeout Jenkins', 'Шаг или директива ограничения времени выбранного участка. Уровень размещения и вложенность определяют, включены ли ожидание агента и все попытки либо только отдельное исполнение.'),
    ('retry Jenkins', 'Повтор тела участка при предусмотренном неуспехе. Повторяет также уже выполненные в теле действия, поэтому допустимость определяется идемпотентностью и характером ошибки, а не выбранным числом попыток.'),
    ('Quiet period', 'Задержка до допуска задачи к началу после события. Она может объединять близкие изменения по политике задания; её следует отличать от ожидания занятого executor и от времени самой команды.'),
    ('Buildable item', 'Готовая к размещению задача во внутренней модели очереди Jenkins. Она уже прошла применимые предыдущие условия, но может ждать подходящего свободного исполнителя.'),
    ('Blocked item', 'Элемент очереди, которому мешает условие блокировки, например ограничение конкуренции. Причину исследуют отдельно от физической загрузки CPU и наличия свободного неподходящего узла.'),
    ('Executor starvation', 'Отсутствие продвижения работы из-за недоступности подходящих исполнителей или структуры ожидания. Пример — родитель держит последний слот и ждёт дочернюю задачу, которой нужен этот же слот.'),
    ('Lockable resource', 'Именованный ресурс, владение которым координирует соответствующий плагин Jenkins. Блокировка согласует участвующие задания, но внешний процесс, не проверяющий эту договорённость, способен обращаться к реальному ресурсу независимо.'),
    ('Throttle category', 'Категория ограничения конкурентного выполнения группы работ. Её глобальный или узловой предел дополняет число executor; цепочка заданий способна сама исчерпать категорию и создать взаимное ожидание.'),
    ('Branch Source', 'Интеграция, описывающая обнаружение веток и запросов изменений в определённом SCM. От неё зависят API, доверие, режим подготовленного слияния и обработка уведомлений.'),
    ('Индексирование Multibranch', 'Исследование источника SCM для обновления набора дочерних заданий и их состояния. Это отдельный этап до или рядом с запуском сборок; длительность API-обхода не равна очереди рабочего агента.'),
    ('Scan credentials', 'Учётные данные для исследования репозиториев и веток через API источника. Их полномочия и место использования отличаются от получения рабочих файлов и публикации утверждённого выпуска.'),
    ('Checkout credentials', 'Учётные данные, используемые для получения исходников. Доступ на чтение репозитория не должен автоматически давать права публикации артефактов или управления инфраструктурой.'),
    ('SCM polling', 'Периодическая проверка изменений источника по инициативе Jenkins. Она отличается от безусловного запуска по расписанию и от webhook, который присылает сам сервер SCM.'),
    ('Осиротевшее задание', 'Дочерний объект многоветочного или организационного проекта, источник которого больше не обнаруживается. Политика удержания определяет срок жизни его истории и может затронуть хранимые там артефакты.'),
    ('Thread dump JVM', 'Снимок стеков и состояний Java-потоков в определённый момент. Несколько сопоставимых снимков помогают исследовать устойчивое ожидание и блокировки; один WAITING-поток не является доказательством зависания.'),
    ('Heap dump JVM', 'Подробный снимок управляемой кучи для исследования объектов и путей удержания памяти. Создание может требовать места и паузы, а содержимое способно включать секреты, поэтому файл не публикуют как обычный журнал.'),
    ('Log recorder Jenkins', 'Настраиваемый сбор журналов выбранных категорий и уровней внутри Jenkins. Применяется для ограниченного диагностического окна; избыточная детализация повышает нагрузку и риск сохранения чувствительного текста.'),
    ('Активный плагин', 'Компонент, действительно загруженный текущим процессом Jenkins. Скачанный новый архив, ожидающий перезапуска, не обязательно совпадает с исполняемой сейчас версией.'),
    ('Artifact Manager Jenkins', 'Настроенный механизм хранения и получения артефактов, который может использовать отдельное внешнее хранилище. Метаданные запуска и физические байты продукта резервируются и удерживаются по согласованным правилам.'),
    ('Restart from Stage', 'Повтор маршрута Declarative Pipeline от выбранной стадии при выполненных требованиях сохранения данных. Это отличается от продолжения исходного ожидающего шага и может повторять побочные действия выбранного участка.'),
    ('Replay Pipeline', 'Повторный запуск управляющей программы Pipeline с возможностью изменения применимого кода. Он создаёт отдельное выполнение с собственной идентичностью, поэтому результат нельзя считать неизменённым продолжением прежнего запуска.'),
]
